        command = f'ping -n 2 {host}'
    else:  # Linux/Mac
        command = f'ping -c 2 {host}'

    try:
        result = subprocess.check_output(command, shell=True, stderr=subprocess.STDOUT, timeout=5)
        return f"<h2>Ping Results:</h2><pre>{result.decode()}</pre>"
